(r, big) => {
    const n = big ? 100000 : r.int(1, 10), ops = [], st = [];
    const lim = 1000000;
    for (let i = 0; i < n; i++) {
      const choices = ["num", "num"];
      if (st.length >= 2 && Math.abs(st[st.length - 1] + st[st.length - 2]) <= lim) choices.push("+");
      if (st.length >= 1 && Math.abs(2 * st[st.length - 1]) <= lim) choices.push("x2");
      if (st.length >= 1) choices.push("undo");
      const c = r.pick(choices);
      if (c === "num") { const v = big ? r.int(-30000, 30000) : r.int(-9, 9); ops.push(String(v)); st.push(v); }
      else if (c === "+") { ops.push("+"); st.push(st[st.length - 1] + st[st.length - 2]); }
      else if (c === "x2") { ops.push("x2"); st.push(2 * st[st.length - 1]); }
      else { ops.push("undo"); st.pop(); }
    }
    return [ops];
  }

