function sheetTotal(ops: string[]): number {
  const st: number[] = [];
  for (const op of ops) {
    if (op === "+") st.push(st[st.length - 1] + st[st.length - 2]);
    else if (op === "x2") st.push(2 * st[st.length - 1]);
    else if (op === "undo") st.pop();
    else st.push(Number(op));
  }
  return st.reduce((a, b) => a + b, 0);
}

