class Solution:
    def sheetTotal(self, ops: List[str]) -> int:
        st = []
        for op in ops:
            if op == "+":
                st.append(st[-1] + st[-2])
            elif op == "x2":
                st.append(2 * st[-1])
            elif op == "undo":
                st.pop()
            else:
                st.append(int(op))
        return sum(st)

