  const st: number[] = [];
  let total = 0;
  const push = (v: number) => { st.push(v); total += v; };
  for (const op of ops) {
    if (op === "+") push(st[st.length - 1] + st[st.length - 2]);
    else if (op === "x2") push(2 * st[st.length - 1]);
    else if (op === "undo") total -= st.pop()!;
    else push(Number(op));
  }
  return total;
}

